package com.example.playaudiovideo; import android.media.MediaPlayer; import android.os.Bundle; import android.view.View; import android.widget.Button; import android.widget.VideoView; import androidx.appcompat.app.AppCompatActivity; public class MainActivity extends AppCompatActivity { MediaPlayer mediaPlayer; VideoView vvPlayer; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);vvPlayer=findViewById(R.id.vvPlayer);vvPlayer.setVideoPath("android.resource://"+getPackageName()+"/"+R.raw.video);mediaPlayer=MediaPlayer.create(this,R.raw.audio);} public void toggleVideo(View v){Button b=(Button)v;if(vvPlayer.isPlaying()){vvPlayer.pause();b.setText("Play Video");}else{vvPlayer.start();b.setText("Pause Video");}} public void toggleAudio(View v){Button b=(Button)v;if(mediaPlayer!=null){if(mediaPlayer.isPlaying()){mediaPlayer.pause();b.setText("Play Audio");}else{mediaPlayer.start();b.setText("Pause Audio");}}} @Override protected void onDestroy(){if(mediaPlayer!=null){mediaPlayer.release();mediaPlayer=null;}super.onDestroy();}}
